-- Cert: revisionsöversikten (2026-11-12). SE:s kravlista, en rad per krav, med två bockar som admin sätter:
-- klar och uppladdad_se. Raderna är data/se-kravlista.csv (78 krav, SE:s egna kravnummer) — en migration kan inte
-- läsa en fil ur repot, så raderna står här; lib/cert/kravlista.test.ts kräver att filen och migrationen är lika.
-- kalla = 'utbildning': kravet bockas inte av för hand, läget räknas ur Utbildning (3.1.1, 3.1.8–3.1.11).
-- Rör inga befintliga tabeller.

create table public.cert_krav (
  krav_nr text primary key,
  namn text not null,
  se_sektion_nr int not null,
  se_sektion text not null,
  galler_oss text not null check (galler_oss in ('Ja', 'Nej', 'Om aktuellt')),
  hog text not null,
  underlag text not null,
  hur_ofta text not null,
  i_skogsystem text not null,
  var_finns_idag text not null,
  klar boolean not null default false,
  uppladdad_se boolean not null default false,
  kalla text check (kalla is null or kalla = 'utbildning'),
  andrad timestamptz not null default now()
);

alter table public.cert_krav enable row level security;
-- Bara admin läser och skriver. Ingen policy för andra = inga rader.
create policy cert_krav_admin on public.cert_krav for all to authenticated
  using ((select public.ar_admin())) with check ((select public.ar_admin()));
revoke all on public.cert_krav from anon;

